mapper.update:
UPDATE t_user_account
SET locked_until=CASE WHEN consecutive_password_failures+1>=#{threshold} THEN #{lockedUntil} ELSE NULL END,
consecutive_password_failures=consecutive_password_failures+1, last_password_failure_time=#{now},
version=version+1, update_time=#{now}
WHERE account_id=#{id}
AND realm='OPERATIONS'
AND status='ACTIVE'
AND credential_version=#{expectedCredentialVersion}
AND (locked_until IS NULL OR locked_until<=#{now})

UPDATE t_user_account
SET consecutive_password_failures=0, locked_until=NULL, last_password_failure_time=NULL, version=version+1,
update_time=#{now}
WHERE account_id=#{id}
AND realm='OPERATIONS'
AND status='ACTIVE'
AND version=#{expectedVersion}
AND credential_version=#{expectedCredentialVersion}
AND auth_epoch=#{expectedAuthEpoch}
AND (locked_until IS NULL OR locked_until<=#{now})

UPDATE t_refresh_token_generation
SET status='CONSUMED', active_slot=NULL, consumed_time=#{now}, version=version+1, update_time=#{now}
WHERE refresh_generation_id=#{id}
AND status='ISSUED'
AND active_slot=1
AND generation_no=#{expectedGeneration}
AND expires_time>#{now}

UPDATE t_auth_session
SET current_generation_no=#{nextGeneration}, last_activity_time=#{now}, idle_expire_time=#{idle},
version=version+1, update_time=#{now}
WHERE session_id=#{id}
AND status='ACTIVE'
AND current_generation_no=#{expectedGeneration}
AND account_auth_epoch=#{expectedAuthEpoch}
AND credential_version_snapshot=#{expectedCredentialVersion}

UPDATE t_auth_session
SET status=#{status}, revocation_reason=#{reason}, revoked_time=#{now}, version=version+1, update_time=#{now}
WHERE session_id=#{id}
AND status='ACTIVE'

UPDATE t_refresh_token_generation
SET status='REVOKED', active_slot=NULL, version=version+1, update_time=#{now}
WHERE session_id=#{id}
AND status='ISSUED'

UPDATE t_user_account
SET credential_version=credential_version+1, auth_epoch=auth_epoch+1, version=version+1, update_time=#{now}
WHERE account_id=#{id}
AND realm='OPERATIONS'
AND status='ACTIVE'
AND version=#{expectedVersion}
AND credential_version=#{expectedCredentialVersion}
AND auth_epoch=#{expectedAuthEpoch}

UPDATE t_password_credential
SET password_verifier_phc=#{verifier}, algorithm_version=19, memory_kib=19456, iterations=2, parallelism=1,
credential_version=credential_version+1, force_change_flag=0, password_changed_time=#{now}, version=version+1,
update_time=#{now}
WHERE account_id=#{id}
AND status='ACTIVE'
AND credential_version=#{expectedCredentialVersion}

UPDATE t_auth_session
SET status=#{status}, revocation_reason=#{reason}, revoked_time=#{now}, version=version+1, update_time=#{now}
WHERE session_id=#{id}
AND account_id=#{accountId}
AND realm='OPERATIONS'
AND channel='OPERATIONS'
AND authentication_method='PASSWORD'
AND status='ACTIVE'
AND account_auth_epoch=#{expectedAuthEpoch}
AND credential_version_snapshot=#{expectedCredentialVersion}

UPDATE t_user_account
SET status='DISABLED', auth_epoch=auth_epoch+1, version=version+1, update_time=#{now}
WHERE account_id=#{id}
AND version=#{version}
AND status='ACTIVE'
AND realm='OPERATIONS'
AND account_type='HUMAN'
AND EXISTS (SELECT 1 FROM t_tenant_member m
    JOIN t_access_tenant t ON t.tenant_id=m.tenant_id
    WHERE m.member_id=#{memberId}
    AND m.account_id=#{id}
    AND m.version=#{memberVersion}
    AND t.tenant_type='INTERNAL'
    AND t.owner_ref_id=1)

UPDATE t_user_account
SET status='DISABLED', auth_epoch=auth_epoch+1, version=version+1, update_time=#{now}
WHERE account_id=#{id}
AND version=#{version}
AND status='ACTIVE'
AND realm='OPERATIONS'
AND account_type='BOOTSTRAP_ADMIN'

UPDATE t_user_account
SET status='ACTIVE', auth_epoch=auth_epoch+1, version=version+1, update_time=#{now}
WHERE account_id=#{id}
AND realm='OPERATIONS'
AND account_type='HUMAN'
AND status='DISABLED'
AND version=#{version}
AND EXISTS (SELECT 1 FROM t_tenant_member m
    WHERE m.member_id=#{memberId}
    AND m.account_id=#{id}
    AND m.version=#{memberVersion})

UPDATE t_user_account
SET status='CLOSED', auth_epoch=auth_epoch+1, version=version+1, update_time=#{now}
WHERE account_id=#{id}
AND realm='OPERATIONS'
AND account_type='HUMAN'
AND status IN ('ACTIVE', 'DISABLED')
AND version=#{version}

UPDATE t_tenant_member
SET status='REVOKED', version=version+1, update_time=#{now}
WHERE member_id=#{id}
AND tenant_id=#{tenantId}
AND version=#{version}

UPDATE t_refresh_token_generation g
JOIN t_auth_session s ON s.session_id=g.session_id
SET g.status='REVOKED', g.active_slot=NULL, g.version=g.version+1, g.update_time=#{now}
WHERE s.account_id=#{id}
AND s.realm='OPERATIONS'
AND g.status='ISSUED'

UPDATE t_password_credential
SET status='REVOKED', version=version+1, update_time=#{now}
WHERE account_id=#{id}
